-- Generated by scripts/generate-blog-cms-import.mjs.
-- Imports the current code-authored articles without replacing any existing CMS row.
begin;

alter table public.blog_posts
  add column if not exists source_origin text not null default 'cms'
    check (source_origin in ('cms', 'code_import')),
  add column if not exists published_snapshot jsonb,
  add column if not exists published_revision_at timestamptz;

create or replace function public.protect_published_blog_identity()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if old.published_snapshot is not null and new.slug is distinct from old.slug then
    raise exception 'The slug of an existing published article is locked. Create a redirect plan before changing its URL.';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_protect_published_blog_identity on public.blog_posts;
create trigger trg_protect_published_blog_identity
before update on public.blog_posts
for each row execute function public.protect_published_blog_identity();

drop policy if exists "Blog editors can delete blog posts" on public.blog_posts;
create policy "Blog editors can delete unpublished blog posts"
on public.blog_posts for delete to authenticated
using (
  ((select public.is_admin_user()) or (select public.is_seo_user()))
  and published_snapshot is null
);

insert into public.blog_posts (
  slug, title, status, readiness, publication_state, category, excerpt, content_blocks,
  cover_image_url, cover_image_alt, seo_title, meta_description, canonical_path,
  og_title, og_description, og_image_url, robots, schema_type,
  breadcrumb_schema_enabled, faq_schema_enabled, faqs, related_slugs, annotations,
  editorial_brief, author_name, reviewer_name, review_scope, review_required,
  reviewed_at, published_at, source_origin, published_snapshot, published_revision_at
)
values
(
    'knowledge-test-practice-victoria-what-to-study',
    'Knowledge Test Practice Victoria: What to Study Before Your ICBC Test',
    'published',
    'awaiting_evidence_review',
    'implemented_locally',
    'Knowledge Test',
    'Use this focused B.C. knowledge-test study map to cover road signs, rules, hazards and practice questions without relying on memorization.',
    '[{"id":"imported-knowledge-test-practice-victoria-what-to-study","type":"rich_html","text":"If you are preparing for a passenger-vehicle knowledge test in Victoria, begin with the material ICBC says to study: Learn to Drive Smart. Practice questions are useful after that foundation because they show where your understanding is still uneven.This guide gives you a study map rather than another bank of unofficial questions. It is intended for Class 5 and 7 passenger-vehicle knowledge preparation. Commercial and motorcycle applicants need the guide for their licence class.Start with the official study sourceICBC describes Learn to Drive Smart as the guide most commonly used by new drivers to prepare for the knowledge test. The guide can be read as one document or chapter by chapter. Use the current version from ICBC so an older download does not become your only source.Do not try to memorize every page in one sitting. Read a section, write down the decision it asks a driver to make, and connect that decision to a road situation. That turns a rule into something you can recognize when a question is worded differently.Use this seven-part study mapStudy each topic for meaning, driver action and changing conditions.TopicWhat to learnHow to check yourselfSigns and markingsWhat the sign, signal or road marking communicates.State the action it requires before looking at an answer.Rules of the roadIntersections, right-of-way, lane use, speed and parking rules.Identify every road user and traffic control in a scenario.See-Think-DoHow observation leads to a safe decision and response.Name the hazard, options and safest lawful action.Sharing the roadResponsibilities around pedestrians, cyclists, large vehicles and other road users.Explain how space and visibility change.Personal strategiesAttention, emotions, fatigue and impairment risks.Choose the action that removes or reduces the risk.EmergenciesHow to respond when ordinary driving conditions break down.Separate prevention from the immediate response.Your licenceLicence stages, responsibilities and restrictions that apply to the question.Check the current ICBC page when a rule may have changed.Study road signs as decisions, not picturesA sign question is not only asking whether you remember a name. Ask three things: what does the sign communicate, who or what could be affected, and what should the driver do next? Group signs by purpose, then mix the groups once recognition becomes easier.ICBC provides a road-sign practice option through its official practice-test page. Our road-sign and rules study guide explains how to turn each missed sign into a useful review note.Build a mistake log that points back to the ruleFor each uncertain or incorrect practice answer, record the topic, what you misunderstood, the rule in the official guide and one clue you should notice next time. Avoid copying the answer alone. Your note should still help when a later question uses different details.Topic: the section of the guide involved.Missed clue: the sign, road user, condition or word that changed the decision.Rule: your short explanation based on the official source.Next check: one new scenario you can use to test the same idea.Move from topic practice to mixed practiceTopic practice is helpful while you are learning. Mixed practice is helpful when you need to recognize which rule applies without being told the category. Use both. If your mixed results reveal the same weakness more than once, return to that chapter before doing more random questions.ICBC says its passenger-vehicle knowledge test has 50 multiple-choice questions and requires 40 correct answers to pass. Treat that threshold as the test requirement, not as a reason to ignore material you find difficult. Review ICBC''s current Get your L instructions before test day.Use a final readiness checklistI have studied the current Learn to Drive Smart guide.I can explain signs and rules instead of naming answers from memory.I have reviewed repeated mistakes by topic.I can work through mixed scenarios without rushing.I have checked ICBC''s current test and licensing instructions.For the application process, fees, identification and online-versus-in-person options, use our B.C. Class 7 knowledge-test guide. If you want structured support, review the Knowledge Test Prep Course or contact the school to confirm current availability.","html":"<p>If you are preparing for a passenger-vehicle knowledge test in Victoria, begin with the material ICBC says to study: <a href=\"https://www.icbc.com/driver-licensing/driving-guides/Learn-to-Drive-Smart\" target=\"_blank\" rel=\"noopener noreferrer\">Learn to Drive Smart</a>. Practice questions are useful after that foundation because they show where your understanding is still uneven.</p><p>This guide gives you a study map rather than another bank of unofficial questions. It is intended for Class 5 and 7 passenger-vehicle knowledge preparation. Commercial and motorcycle applicants need the guide for their licence class.</p><h2>Start with the official study source</h2><p>ICBC describes Learn to Drive Smart as the guide most commonly used by new drivers to prepare for the knowledge test. The guide can be read as one document or chapter by chapter. Use the current version from ICBC so an older download does not become your only source.</p><p>Do not try to memorize every page in one sitting. Read a section, write down the decision it asks a driver to make, and connect that decision to a road situation. That turns a rule into something you can recognize when a question is worded differently.</p><h2>Use this seven-part study map</h2><div class=\"overflow-x-auto rounded-xl border border-slate-200\" role=\"region\" aria-label=\"Knowledge test study map\" tabindex=\"0\"><table><caption>Study each topic for meaning, driver action and changing conditions.</caption><thead><tr><th scope=\"col\">Topic</th><th scope=\"col\">What to learn</th><th scope=\"col\">How to check yourself</th></tr></thead><tbody><tr><th scope=\"row\">Signs and markings</th><td>What the sign, signal or road marking communicates.</td><td>State the action it requires before looking at an answer.</td></tr><tr><th scope=\"row\">Rules of the road</th><td>Intersections, right-of-way, lane use, speed and parking rules.</td><td>Identify every road user and traffic control in a scenario.</td></tr><tr><th scope=\"row\">See-Think-Do</th><td>How observation leads to a safe decision and response.</td><td>Name the hazard, options and safest lawful action.</td></tr><tr><th scope=\"row\">Sharing the road</th><td>Responsibilities around pedestrians, cyclists, large vehicles and other road users.</td><td>Explain how space and visibility change.</td></tr><tr><th scope=\"row\">Personal strategies</th><td>Attention, emotions, fatigue and impairment risks.</td><td>Choose the action that removes or reduces the risk.</td></tr><tr><th scope=\"row\">Emergencies</th><td>How to respond when ordinary driving conditions break down.</td><td>Separate prevention from the immediate response.</td></tr><tr><th scope=\"row\">Your licence</th><td>Licence stages, responsibilities and restrictions that apply to the question.</td><td>Check the current ICBC page when a rule may have changed.</td></tr></tbody></table></div><h2>Study road signs as decisions, not pictures</h2><p>A sign question is not only asking whether you remember a name. Ask three things: what does the sign communicate, who or what could be affected, and what should the driver do next? Group signs by purpose, then mix the groups once recognition becomes easier.</p><p>ICBC provides a road-sign practice option through its <a href=\"https://www.icbc.com/driver-licensing/new-drivers/practice-knowledge-test\" target=\"_blank\" rel=\"noopener noreferrer\">official practice-test page</a>. Our <a href=\"/blog/knowledge-test-practice-langford-road-signs\">road-sign and rules study guide</a> explains how to turn each missed sign into a useful review note.</p><h2>Build a mistake log that points back to the rule</h2><p>For each uncertain or incorrect practice answer, record the topic, what you misunderstood, the rule in the official guide and one clue you should notice next time. Avoid copying the answer alone. Your note should still help when a later question uses different details.</p><ul><li><strong>Topic:</strong> the section of the guide involved.</li><li><strong>Missed clue:</strong> the sign, road user, condition or word that changed the decision.</li><li><strong>Rule:</strong> your short explanation based on the official source.</li><li><strong>Next check:</strong> one new scenario you can use to test the same idea.</li></ul><h2>Move from topic practice to mixed practice</h2><p>Topic practice is helpful while you are learning. Mixed practice is helpful when you need to recognize which rule applies without being told the category. Use both. If your mixed results reveal the same weakness more than once, return to that chapter before doing more random questions.</p><p>ICBC says its passenger-vehicle knowledge test has 50 multiple-choice questions and requires 40 correct answers to pass. Treat that threshold as the test requirement, not as a reason to ignore material you find difficult. Review ICBC&#x27;s <a href=\"https://www.icbc.com/driver-licensing/new-drivers/Get-your-L\" target=\"_blank\" rel=\"noopener noreferrer\">current Get your L instructions</a> before test day.</p><h2>Use a final readiness checklist</h2><ul><li>I have studied the current Learn to Drive Smart guide.</li><li>I can explain signs and rules instead of naming answers from memory.</li><li>I have reviewed repeated mistakes by topic.</li><li>I can work through mixed scenarios without rushing.</li><li>I have checked ICBC&#x27;s current test and licensing instructions.</li></ul><p>For the application process, fees, identification and online-versus-in-person options, use our <a href=\"/knowledge-test-guide\">B.C. Class 7 knowledge-test guide</a>. If you want structured support, review the <a href=\"/courses/knowledge-test-prep-course\">Knowledge Test Prep Course</a> or contact the school to confirm current availability.</p>"}]'::jsonb,
