    '[{"id":"imported-knowledge-test-practice-langford-confidence-faq-1","question":"How can I feel more confident before the ICBC knowledge test?","answer":"Use a repeatable study routine, track weak topics and practise explaining the rule behind each answer. Confidence is more reliable when it comes from evidence of understanding rather than one high score."},{"id":"imported-knowledge-test-practice-langford-confidence-faq-2","question":"Should I keep practising after I get a high score?","answer":"Check whether the score is consistent across mixed topics and whether you can explain uncertain answers. If the score depends on recognizing the same question order, return to the guide and vary your practice."},{"id":"imported-knowledge-test-practice-langford-confidence-faq-3","question":"What should I do if a practice question confuses me?","answer":"Identify the topic and return to the current Learn to Drive Smart section. Write the rule in your own words, note the clue you missed and test it later with a changed scenario."}]'::jsonb,
    '["knowledge-test-practice-langford-step-by-step","knowledge-test-practice-victoria-common-questions","knowledge-test-practice-langford-road-signs"]'::jsonb,
