    '{"primaryReader":"","targetQuestion":"","location":"Victoria, British Columbia","intendedOutcome":"","scope":"Imported from the current code-authored article.","overlap":"Existing public article with the same stable slug.","evidenceGaps":"Recheck time-sensitive claims and record the evidence used for the proposed revision.","originalContribution":"","responsibleAuthor":"Alden","nextStep":"","maintenanceDate":""}'::jsonb,
